-- Role assignment integrity (Phase 1 slice 1.6; database review of slice 1.5,
-- docs/platform-deferred.md "Role assignment integrity"). Generated by prisma migrate diff, then
-- hand-edited where marked.

-- DropForeignKey
ALTER TABLE "identity"."role_assignment" DROP CONSTRAINT "role_assignment_role_fkey";

-- DropIndex: the new unique key below leads with (tenant_id, account_id) and serves its reads.
DROP INDEX "identity"."role_assignment_tenant_id_account_id_idx";

-- CreateIndex
CREATE UNIQUE INDEX "role_tenant_id_id_scope_key" ON "identity"."role"("tenant_id", "id", "scope");

-- CreateIndex. Hand-edited: NULLS NOT DISTINCT, so a tenant grant (site_id NULL) of a role to
-- an account can exist once too (PostgreSQL 15+; Prisma cannot express it).
CREATE UNIQUE INDEX "role_assignment_tenant_id_account_id_role_id_site_id_key" ON "identity"."role_assignment"("tenant_id", "account_id", "role_id", "site_id") NULLS NOT DISTINCT;

-- AddForeignKey: through the role's scope, so a grant's level is always its role's scope
-- (held-keys.ts repeats the rule in code). A role's scope is never updated (no column grant).
ALTER TABLE "identity"."role_assignment" ADD CONSTRAINT "role_assignment_role_fkey" FOREIGN KEY ("tenant_id", "role_id", "level") REFERENCES "identity"."role"("tenant_id", "id", "scope") ON DELETE RESTRICT ON UPDATE RESTRICT;
